\pset pager off
select 'TBL', table_schema||'.'||table_name||': '||string_agg(column_name||' '||data_type, ', ' order by ordinal_position) from information_schema.columns where table_name in ('ItemStorage','Item') group by table_schema, table_name;
select 'AMY', m."Number", m."NpcWindow", m."ObjectKind", m."MerchantStoreId", m."IntelligenceTypeName", m."AttackSkillId" is null, m."MoveRange", m."ViewRange", m."RespawnDelay", m."Attribute", m."NumberOfMaximumItemDrops", m."IsActive", m."IntroducedIn" from config."MonsterDefinition" m where m."Number" in (253, 725, 726);
select 'ITEM', i."ItemSlot", i."Durability", i."Level", i."HasSkill", (select "Group"||':'||"Number" from config."ItemDefinition" d where d."Id"=i."DefinitionId") from config."Item" i where i."ItemStorageId"=(select "MerchantStoreId" from config."MonsterDefinition" where "Number"=253) order by 2 limit 5;
select 'SPAWN', s."X1", s."Y1", s."X2", s."Y2", s."Direction", s."Quantity", s."SpawnTrigger", g."Number" from config."MonsterSpawnArea" s join config."GameMapDefinition" g on g."Id"=s."GameMapId" where s."MonsterDefinitionId"=(select "Id" from config."MonsterDefinition" where "Number"=253);
select 'ELF', s."X1", s."Y1", split_part(m."Designation",'||',1) from config."MonsterSpawnArea" s join config."GameMapDefinition" g on g."Id"=s."GameMapId" join config."MonsterDefinition" m on m."Id"=s."MonsterDefinitionId" where g."Number"=51 and m."NpcWindow"<>0;
